def rearange_string(s):
    # Create a dictionary to store the frequency of each character
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    # Create a list to store the frequency of each character
    freq_list = []
    for char in freq:
        freq_list.append([freq[char], char])
    # Sort the list of frequencies in descending order
    freq_list.sort(reverse=True)
    # Create a list to store the rearranged string
    rearranged_string = []
    # Iterate over the list of frequencies
    for freq in freq_list:
        # Check if the frequency of the current character is odd
        if freq[0] % 2 != 0:
            # If the frequency is odd, add the character to the rearranged string
            rearranged_string.append(freq[1])
    # Return the rearranged string
    return ''.join(rearranged_string)

