def pancake_sort(lst):
    if len(lst) == 1:
        return lst
    pivot = lst[len(lst) // 2]
    left = [x for x in lst if x < pivot]
    middle = [x for x in lst if x == pivot]
    right = [x for x in lst if x > pivot]
    return pancake_sort(left) + pancake_sort(middle) + pancake_sort(right)

