def max_path_sum(triangle, m, n):
    # Base case
    if m == 1:
        return triangle[0][0]
    if m == 2:
        return max(triangle[0][0], triangle[1][0])
    # Recursive case
    return max(triangle[m-1][0], triangle[m-1][1]) + max_path_sum(triangle, m-1, n-1)

