def heap_assending(arr):
    # Create a min-heap
    heap = []
    for i in range(len(arr)):
        heap.append(arr[i])
    # Build the heap
    for i in range(len(arr)):
        heapify(heap, i)
    # Sort the heap
    while len(heap) > 1:
        heap[0], heap[-1] = heap[-1], heap[0]
        heapify(heap, 0)
    return heap

def heapify(heap, i):
    # Get the left child
    left = 2 * i + 1
    # Get the right child
    right = 2 * i + 2
    # Get the smallest child
    if left < len(heap) and heap[left] < heap[i]:
        smallest = left
    else:
        smallest = i
    # Swap the smallest child with the root
    if right < len(heap) and heap[right] < heap[smallest]:
        smallest = right
    # Swap the smallest child with the root
    if smallest != i:
        heap[i], heap[smallest] = heap[smallest], heap[i]
        heapify(heap, smallest)

